namespace LearningMap.Domain.Entities;

public class Employee : IAuditableEntity
{
    public int EmployeeId { get; set; }
    public Guid EmployeeGuid { get; set; }

    /// <summary>
    /// Human-friendly ID shown in the UI, e.g. "EMP-00001". Generated by SQL Server from a
    /// SEQUENCE when the row is inserted, so two simultaneous inserts can never get the same code.
    /// Must start as null: EF only lets the database generate a value when the property still holds
    /// its CLR default. With "" EF would insert the empty string instead.
    /// </summary>
    public string EmployeeCode { get; set; } = null!;

    public string FirstName { get; set; } = string.Empty;
    public string LastName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string? PhoneNumber { get; set; }
    public string Department { get; set; } = string.Empty;
    public string Designation { get; set; } = string.Empty;
    public DateTime DateOfJoining { get; set; }

    /// <summary>
    /// Path of the image inside the blob container, e.g. "employees/{guid}/{random}.png".
    /// We store the NAME, not a URL. URLs are generated on read because SAS URLs expire.
    /// </summary>
    public string? ProfileImageBlobName { get; set; }

    /// <summary>When the current image was uploaded (null = no image).</summary>
    public DateTimeOffset? ImageUploadedDate { get; set; }

    /// <summary>Soft delete: the row stays in the table, it is just hidden (see the EF global query filter).</summary>
    public bool IsDeleted { get; set; }

    public int? CreatedBy { get; set; }
    public DateTimeOffset CreatedDate { get; set; }
    public int? ModifiedBy { get; set; }
    public DateTimeOffset? ModifiedDate { get; set; }
}
